import React from 'react';
import { Link } from 'react-router-dom';

const Home = () => (
  <div className="container">
    <section style={{ backgroundColor: 'var(--soft-yellow)', padding: '50px', borderRadius: 'var(--border-radius)', textAlign: 'center' }}>
      <h1>Nanhe Farishte – Kiran Knits</h1>
      <p>Har bunai mein maa ka pyaar</p>
      <Link to="/products"><button>Shop Now</button></Link>
    </section>
    <section>
      <h2>Categories</h2>
      <div style={{ display: 'flex', justifyContent: 'space-around' }}>
        <Link to="/products?category=Sweater"><div className="card">Sweaters</div></Link>
        <Link to="/products?category=Socks"><div className="card">Socks</div></Link>
        <Link to="/products?category=Cap"><div className="card">Caps</div></Link>
      </div>
    </section>
  </div>
);

export default Home;
